#include <stdio.h>

int main(void) {
    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int b[2][3] = {{6, 5, 4}, {3, 2, 1}};
    int result[2][3] = {0};
    for (size_t row = 0; row < 2; ++row) {
        for (size_t col = 0; col < 3; ++col) {
            result[row][col] = a[row][col] + b[row][col];
            printf("%d%c", result[row][col], col == 2 ? '\n' : ' ');
        }
    }
    return 0;
}
